        "All": "select finalstatus.text_ as \"Settlement Action\", finalselectedtxn.text_ as \"Associated Transaction\", CASE WHEN  hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN  closedby.user_id_ is not null THEN closedby.user_id_ ELSE ''Auto Closed'' END ELSE null END as \"Closed By\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' else  cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END  as \"VPA\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' else  cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''observations''->''account''->>''vcexternalaccountid'' END  as \"Account\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''observations''->''customer''->>''vcexternalcustid'' else  cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''observations''->''customer''->>''vcexternalcustid'' END  as \"Customer\", hiproinst.end_time_  as  \"Closed Date\", CASE WHEN  hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END as \"Stage\", task.assignee_ as \"Claimed By\", hiproinst.start_time_  as  \"Created Date\", CASE WHEN hiproinst.state_ != ''ACTIVE'' then ''Closed'' WHEN  task.assignee_ is not null THEN ''Claimed'' ELSE ''Unclaimed'' END as \"Status\", pdef.name_ as \"Case Type\", CASE WHEN  task.assignee_ is not null and oplog.timestamp_ is not null THEN oplog.timestamp_ WHEN  task.assignee_ is not null and oplog.timestamp_ is null THEN task.create_time_ ELSE null END  as \"Claimed On\", payer.text_ as \"Payer\", payee.text_ as \"Payee\", TransactionAmount.double_ / 100 as \"Amount\", TicketID.long_ as \"Case ID\", Alert